{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C52"],
      "claim": "Maraviroc, a high-transfer analogue with aromatic, amide, and cyclohexyl features, has absolute oral bioavailability of 33% at 300 mg and 23% at 100 mg in humans, supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Perindopril, an ester prodrug with a proline-like carboxylic acid, has absolute oral bioavailability of about 75% in humans, supporting high F for the ester-containing query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "SAHA (vorinostat) has 43% absolute oral bioavailability in humans after oral dosing, supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Labetalol, despite extensive first-pass metabolism, has systemic availability of 33% after oral administration, supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Actisomide has absolute oral bioavailability of 30-43% in humans, supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "A stavudine phosphoramidate prodrug is reported to have high oral bioavailability, supporting high F for a phosphonate/ester prodrug-like query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple high-transfer analogues with measured human oral bioavailability values of 23-75% support F ≥20% for the query. The only sub-20 value is for perindoprilat formed from perindopril, an active metabolite rather than the administered parent, and is outweighed by the consistent high-F evidence from ester prodrugs and related phosphonate/nucleoside analogues.",
  "evidence_gaps": [
    "No direct human pharmacokinetic data exist for the query molecule itself.",
    "The query contains a phosphinate/phosphonate and a free carboxylic acid, whose effects on permeability and first-pass metabolism are not directly measured.",
    "The sub-20 perindoprilat value reflects metabolite formation from a prodrug, not parent-drug bioavailability, limiting its direct applicability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

